<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Donation; use App\Models\Expense; use Dompdf\Dompdf; use Dompdf\Options;
class ReportExportController extends Controller { public function donationsCsv(){ $rows=Donation::where('status','completed')->latest()->get(['id','name','email','amount','currency','payment_method','status','created_at']); $file='donations-'.now()->format('Ymd-His').'.csv'; return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['ID','Name','Email','Amount','Currency','Method','Status','Date']);foreach($rows as $x)fputcsv($out,$x->toArray());fclose($out);},$file,['Content-Type'=>'text/csv']); }
 public function expensesCsv(){ $rows=Expense::latest()->get(['id','category','amount','expense_date','description']); $file='expenses-'.now()->format('Ymd-His').'.csv'; return response()->streamDownload(function()use($rows){$o=fopen('php://output','w');fputcsv($o,['ID','Category','Amount','Date','Description']);foreach($rows as $x)fputcsv($o,$x->toArray());fclose($o);},$file,['Content-Type'=>'text/csv']); }
 public function donationsPdf(){ $rows=Donation::where('status','completed')->latest()->limit(500)->get(); $html=view('admin.reports.donations-pdf',compact('rows'))->render(); $options=new Options();$options->set('isRemoteEnabled',false);$pdf=new Dompdf($options);$pdf->loadHtml($html);$pdf->setPaper('A4','landscape');$pdf->render(); return response($pdf->output(),200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename="donations-report.pdf"']); }
 public function expensesPdf(){ $rows=Expense::latest()->limit(500)->get(); $html=view('admin.reports.expenses-pdf',compact('rows'))->render(); $options=new Options();$options->set('isRemoteEnabled',false);$pdf=new Dompdf($options);$pdf->loadHtml($html);$pdf->setPaper('A4','landscape');$pdf->render(); return response($pdf->output(),200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename="expenses-report.pdf"']); }
}
